(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[678]={"source_order":678,"notes":["The folio number could be read as '339b' or '339ᵇ.'; the superscript letter is small.","Faint mirror-image writing shows through across the whole page. It matches the facing recto of fol. 339, with shelfmarks in the left column, titles in the main column and extent at the right. It is bleed-through, not writing on this page, and is not transcribed.","At the far right, beyond the gutter at about x=3100, are cut-off fragments of the facing page fol. 340: 'd.25…' at about [3340,700,170,80], 'e 25…' at about [3360,940,150,70], 'e 253' at about [3310,1760,200,70] and 'e254' at about [3280,2690,210,70]. These belong to fol. 340 and are not target-page records.","I reviewed the whole page in the overview and in all six native tiles, covering the top, middle, bottom, the outer margin, the gutter and the interlinear spaces. Apart from the folio number '339ᵇ.', the ruled page has no catalogue entries, headings, cross-references or marginal notes.","Faint mirror-image writing shows through across the page, with shelfmark, title and extent columns. It matches the reverse of the recto of fol. 339 (source order 677) and is bleed-through, not writing on this page, so it is not transcribed.","Small dark specks occur in the main column, at about [1180,1750] and in the right part near [2650,1020]-[2680,1160]. A few further dots are scattered across the page. These are not text.","Beyond the gutter at about x≈3100 there are cut-off shelfmark fragments of the facing page fol. 340 (source order 679): 'd.25…' at about [3340,700,170,80], 'e 25…' at about [3360,940,150,70], 'e 25…' at about [3310,1760,200,70] and 'e254' at about [3280,2690,210,70]. They belong to fol. 340, whose own image shows d.250, e 252, e 253 and e254. They are not target-page records."],"records":[{"id":"css-prod-0678-r001","local_id":"r001","source_order":678,"folio":"339b","folio_label":"fol. 339b","sequence":1,"page_id":"21a08a68-873a-4417-aa96-0d4c574785b1","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"339ᵇ.","annotations":["Folio number in the top left (shelfmark-column) margin, written in pencil or dark ink, with a small raised letter after '339' followed by a dot."],"uncertainties":["The raised letter is small. It most likely reads 'b', which agrees with the supplied folio label fol. 339b, but it could be misread as '6'.","The trailing mark may be a full stop or a stray dot."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[450,340,170,120]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/21a08a68-873a-4417-aa96-0d4c574785b1.json","auditPath":"audit/pages/0678.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
